1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service 在 Store 之上实现班次交接的全部业务规则。
11	type Service struct {
12		store *Store
13		now   func() time.Time
14	}
15	
16	// NewService 创建业务服务。
17	func NewService(store *Store) *Service {
18		return &Service{store: store, now: time.Now}
19	}
20	
21	// nowAt 供测试固定处理时间。
22	func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }
23	
24	func clean(s string) string { return strings.TrimSpace(s) }
25	
26	// 事项历史中的接收说明模板。新写入的 received 事件用交接编号、交班、接班班次
27	// 与接收方式完整标注；item-show 合并接收记录时依据这些明确记载判定同一次接收，
28	// 不能仅凭操作人与时刻合并。模板为固定格式，parseReceivedDetail 据其解析。
29	const (
30		receivedDetailPrefix = "交接 "
31		receivedDetailMid    = "（"
32		receivedDetailArrow  = " -> "
33		receivedDetailTail   = "）接班班次接收："
34		// 旧版本写入的说明只明确记载接班班次与接收方式，没有交接编号与交班班次，
35		// 例如“接班班次 S002 接收：确认接收”。其中明确记载的事实仍可用于比对，
36		// 未记载的字段不比较，更不凭空补齐。
37		legacyReceivedPrefix = "接班班次 "
38		legacyReceivedTail   = " 接收："
39	)
40	
41	// receivedDetailText 生成接收事件的标准说明，明确记载交接编号、交班、接班班次
42	// 与接收方式；继续跟踪还保留当时的跟踪说明与后续负责人。
43	func receivedDetailText(h *Handover, action EntryAction, statusLabel, trackingNote, nextFollowOwner string) string {
44		s := receivedDetailPrefix + h.ID + receivedDetailMid + h.FromShiftID +
45			receivedDetailArrow + h.ToShiftID + receivedDetailTail + statusLabel
46		if action == ActionTrack {
47			s += "；跟踪说明：" + trackingNote + "；后续负责人：" + nextFollowOwner
48		}
49		return s
50	}
51	
52	// receivedAttribution 是从接收说明中明确解析出的归属信息。空字符串表示该
53	// 说明没有明确记载这一项，比对时不得据此判断一致或矛盾。
54	type receivedAttribution struct {
55		handoverID string
56		fromShift  string
57		toShift    string
58		kind       string // confirm/track，无法确定时为 ""
59	}
60	
61	// receivedKindFromLabel 只识别两种已保存的接收方式中文名；track 的说明后还
62	// 带有“；跟踪说明：…”后缀。无法识别返回 ""，不据其他信息猜测。
63	func receivedKindFromLabel(label string) string {
64		switch {
65		case label == EntryConfirmed.Label():
66			return "confirm"
67		case label == EntryTracking.Label() || strings.HasPrefix(label, EntryTracking.Label()+"；"):
68			return "track"
69		}
70		return ""
71	}
72	
73	// parseReceivedDetail 只解析本工具写入的固定格式说明（含旧版本格式），提取
74	// 其中明确记载的交接编号、交班、接班班次与接收方式。其他文字（外部写入或
75	// 残缺的说明）一律视为没有明确记载，返回 ok=false，绝不靠猜测补全。
76	func parseReceivedDetail(detail string) (receivedAttribution, bool) {
77		switch {
78		case strings.HasPrefix(detail, receivedDetailPrefix):
79			rest := detail[len(receivedDetailPrefix):]
80			pi := strings.Index(rest, receivedDetailMid)
81			ai := strings.Index(rest, receivedDetailArrow)
82			ti := strings.Index(rest, receivedDetailTail)
83			if pi <= 0 || ai < 0 || ti < 0 || !(pi < ai && ai+len(receivedDetailArrow) < ti) {
84				return receivedAttribution{}, false
85			}
86			hid := rest[:pi]
87			from := rest[pi+len(receivedDetailMid) : ai]
88			to := rest[ai+len(receivedDetailArrow) : ti]
89			kind := receivedKindFromLabel(rest[ti+len(receivedDetailTail):])
90			if hid == "" || from == "" || to == "" || kind == "" {
91				return receivedAttribution{}, false
92			}
93			return receivedAttribution{handoverID: hid, fromShift: from, toShift: to, kind: kind}, true
94		case strings.HasPrefix(detail, legacyReceivedPrefix):
95			rest := detail[len(legacyReceivedPrefix):]
96			ti := strings.Index(rest, legacyReceivedTail)
97			if ti <= 0 {
98				return receivedAttribution{}, false
99			}
100			to := rest[:ti]
101			kind := receivedKindFromLabel(rest[ti+len(legacyReceivedTail):])
102			if to == "" || kind == "" {
103				return receivedAttribution{}, false
104			}
105			// 旧格式只明确记载接班班次与接收方式；交接编号、交班班次未记载。
106			return receivedAttribution{toShift: to, kind: kind}, true
107		}
108		return receivedAttribution{}, false
109	}
110	
111	func requireNonEmpty(field, v string) error {
112		if clean(v) == "" {
113			return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
114		}
115		return nil
116	}
117	
118	func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
119		// 前班结束恰好等于后班开始（端点相等）不算重叠。
120		return s1.Before(e2) && s2.Before(e1)
121	}
122	
123	// notePair 返回无序班次编号对，作为重叠说明的稳定键。
124	func notePair(a, b string) (string, string) {
125		if a <= b {
126			return a, b
127		}
128		return b, a
129	}
130	
131	func findShift(d *Data, id string) (*Shift, int) {
132		for i := range d.Shifts {
133			if d.Shifts[i].ID == id {
134				return &d.Shifts[i], i
135			}
136		}
137		return nil, -1
138	}
139	
140	func findItem(d *Data, id string) (*Item, int) {
141		for i := range d.Items {
142			if d.Items[i].ID == id {
143				return &d.Items[i], i
144			}
145		}
146		return nil, -1
147	}
148	
149	func findHandover(d *Data, id string) (*Handover, int) {
150		for i := range d.Handovers {
151			if d.Handovers[i].ID == id {
152				return &d.Handovers[i], i
153			}
154		}
155		return nil, -1
156	}
157	
158	func findEntry(h *Handover, itemID string) (*HandoverEntry, int) {
159		for i := range h.Entries {
160			if h.Entries[i].ItemID == itemID {
161				return &h.Entries[i], i
162			}
163		}
164		return nil, -1
165	}
166	
167	func findNote(d *Data, a, b string) *OverlapNote {
168		x, y := notePair(a, b)
169		for i := range d.Notes {
170			if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y {
171				return &d.Notes[i]
172			}
173		}
174		return nil
175	}
176	
177	// currentItemsOfShift 返回与某班次相关的当前事项，按编号排列、每项只列一次。
178	// 用于进行中班次的当前信息展示，以及缺少结束时记录的旧数据班次。
179	func currentItemsOfShift(d *Data, shiftID string) []Item {
180		out := []Item{}
181		seen := map[string]bool{}
182		for _, it := range d.Items {
183			if seen[it.ID] {
184				continue
185			}
186			if it.OriginShiftID == shiftID || it.CurrentShiftID == shiftID || contains(it.ShiftIDs, shiftID) {
187				seen[it.ID] = true
188				out = append(out, it)
189			}
190		}
191		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
192		return out
193	}
194	
195	func hasNote(d *Data, a, b string) bool { return findNote(d, a, b) != nil }
196	
197	// CreateShift 建立班次。岗位、负责人必填，结束时间必须晚于开始时间。
198	// 同一岗位按实际时刻比较区间：前班结束恰好等于后班开始不算重叠；
199	// 与同岗位已存班次存在重叠时 overlapNote 必须非空，说明会一并保存。
200	// 不同岗位互不影响。
201	func (svc *Service) CreateShift(position, owner string, start, end time.Time, overlapNote string) (Shift, error) {
202		position = clean(position)
203		owner = clean(owner)
204		overlapNote = clean(overlapNote)
205		if err := requireNonEmpty("岗位", position); err != nil {
206			return Shift{}, err
207		}
208		if err := requireNonEmpty("负责人", owner); err != nil {
209			return Shift{}, err
210		}
211		if !end.After(start) {
212			return Shift{}, fmt.Errorf("%w：结束时间必须晚于开始时间（开始 %s，结束 %s）",
213				ErrInvalidInput, start.Format(time.RFC3339), end.Format(time.RFC3339))
214		}
215	
216		var created Shift
217		err := svc.store.mutate(func(d *Data) error {
218			var overlapping []Shift
219			for _, sh := range d.Shifts {
220				if sh.Position == position && intervalsOverlap(start, end, sh.Start, sh.End) {
221					overlapping = append(overlapping, sh)
222				}
223			}
224			if len(overlapping) > 0 && overlapNote == "" {
225				ids := make([]string, len(overlapping))
226				for i, sh := range overlapping {
227					ids[i] = fmt.Sprintf("%s（%s ~ %s）", sh.ID, sh.Start.Format(time.RFC3339), sh.End.Format(time.RFC3339))
228				}
229				return fmt.Errorf("%w：与同岗位班次 %s 区间重叠，必须填写重叠说明",
230					ErrOverlap, strings.Join(ids, "、"))
231			}
232	
233			d.ShiftSeq++
234			now := svc.now()
235			created = Shift{
236				ID:        fmt.Sprintf("S%03d", d.ShiftSeq),
237				Position:  position,
238				Owner:     owner,
239				Start:     start,
240				End:       end,
241				CreatedAt: now,
242			}
243			d.Shifts = append(d.Shifts, created)
244	
245			// 为每个尚未登记说明的重叠班次保存说明；已有说明的不重复保存。
246			for _, sh := range overlapping {
247				if findNote(d, created.ID, sh.ID) != nil {
248					continue
249				}
250				d.NoteSeq++
251				x, y := notePair(created.ID, sh.ID)
252				d.Notes = append(d.Notes, OverlapNote{
253					ID:        fmt.Sprintf("N%03d", d.NoteSeq),
254					Position:  position,
255					ShiftA:    x,
256					ShiftB:    y,
257					Note:      overlapNote,
258					CreatedAt: now,
259				})
260			}
261			return nil
262		})
263		return created, err
264	}
265	
266	// AddOverlapNote 为同岗位两个重叠班次保存重叠说明。
267	func (svc *Service) AddOverlapNote(shiftA, shiftB, note string) (OverlapNote, error) {
268		note = clean(note)
269		if err := requireNonEmpty("重叠说明", note); err != nil {
270			return OverlapNote{}, err
271		}
272		if clean(shiftA) == clean(shiftB) {
273			return OverlapNote{}, fmt.Errorf("%w：重叠说明需要两个不同的班次", ErrInvalidInput)
274		}
275	
276		var saved OverlapNote
277		err := svc.store.mutate(func(d *Data) error {
278			sa, _ := findShift(d, clean(shiftA))
279			sb, _ := findShift(d, clean(shiftB))
280			if sa == nil || sb == nil {
281				return fmt.Errorf("%w：班次 %s 或 %s 不存在", ErrNotFound, shiftA, shiftB)
282			}
283			if sa.Position != sb.Position {
284				return fmt.Errorf("%w：班次 %s（%s）与 %s（%s）岗位不同，无需重叠说明",
285					ErrPositionMismatch, sa.ID, sa.Position, sb.ID, sb.Position)
286			}
287			if !intervalsOverlap(sa.Start, sa.End, sb.Start, sb.End) {
288				return fmt.Errorf("%w：班次 %s 与 %s 的时间区间不重叠（端点相接不算重叠）",
289					ErrInvalidInput, sa.ID, sb.ID)
290			}
291			d.NoteSeq++
292			x, y := notePair(sa.ID, sb.ID)
293			saved = OverlapNote{
294				ID:        fmt.Sprintf("N%03d", d.NoteSeq),
295				Position:  sa.Position,
296				ShiftA:    x,
297				ShiftB:    y,
298				Note:      note,
299				CreatedAt: svc.now(),
300			}
301			d.Notes = append(d.Notes, saved)
302			return nil
303		})
304		return saved, err
305	}
306	
307	// AddItem 向未结束班次新增事项。内容、严重程度、后续负责人必填，限制条件可空。
308	func (svc *Service) AddItem(shiftID, content string, severity Severity, constraints, followOwner string) (Item, error) {
309		shiftID = clean(shiftID)
310		content = clean(content)
311		constraints = clean(constraints)
312		followOwner = clean(followOwner)
313		if err := requireNonEmpty("事项内容", content); err != nil {
314			return Item{}, err
315		}
316		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
317			return Item{}, err
318		}
319		if !severity.valid() {
320			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
321		}
322	
323		var created Item
324		err := svc.store.mutate(func(d *Data) error {
325			sh, _ := findShift(d, shiftID)
326			if sh == nil {
327				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
328			}
329			if sh.Closed {
330				return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
331			}
332			d.ItemSeq++
333			now := svc.now()
334			created = Item{
335				ID:             fmt.Sprintf("I%03d", d.ItemSeq),
336				OriginShiftID:  sh.ID,
337				ShiftIDs:       []string{sh.ID},
338				CurrentShiftID: sh.ID,
339				Content:        content,
340				Severity:       severity,
341				Constraints:    constraints,
342				FollowOwner:    followOwner,
343				CreatedAt:      now,
344				Events: []ItemEvent{
345					{At: now, Kind: "created", Detail: "事项建立"},
346				},
347			}
348			d.Items = append(d.Items, created)
349			return nil
350		})
351		return created, err
352	}
353	
354	// UpdateItem 在事项所在班次结束前修改其内容、严重程度、限制条件和后续负责人。
355	func (svc *Service) UpdateItem(itemID, content string, severity Severity, constraints, followOwner string) (Item, error) {
356		itemID = clean(itemID)
357		content = clean(content)
358		constraints = clean(constraints)
359		followOwner = clean(followOwner)
360		if err := requireNonEmpty("事项内容", content); err != nil {
361			return Item{}, err
362		}
363		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
364			return Item{}, err
365		}
366		if !severity.valid() {
367			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
368		}
369	
370		var updated Item
371		err := svc.store.mutate(func(d *Data) error {
372			it, _ := findItem(d, itemID)
373			if it == nil {
374				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
375			}
376			sh, _ := findShift(d, it.CurrentShiftID)
377			if sh == nil || sh.Closed {
378				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，内容不能修改",
379					ErrShiftClosed, itemID, it.CurrentShiftID)
380			}
381			changes := []string{}
382			if it.Content != content {
383				changes = append(changes, "内容")
384			}
385			if it.Severity != severity {
386				changes = append(changes, "严重程度")
387			}
388			if it.Constraints != constraints {
389				changes = append(changes, "限制条件")
390			}
391			if it.FollowOwner != followOwner {
392				changes = append(changes, "后续负责人")
393			}
394			it.Content = content
395			it.Severity = severity
396			it.Constraints = constraints
397			it.FollowOwner = followOwner
398			it.Events = append(it.Events, ItemEvent{
399				At:     svc.now(),
400				Kind:   "updated",
401				Detail: "修改字段：" + joinOr(changes, "无变更"),
402			})
403			updated = *it
404			return nil
405		})
406		return updated, err
407	}
408	
409	func joinOr(xs []string, or string) string {
410		if len(xs) == 0 {
411			return or
412		}
413		return strings.Join(xs, "、")
414	}
415	
416	// CloseItem 在事项所在班次结束前关闭该事项，须填写操作人。
417	func (svc *Service) CloseItem(itemID, operator string) (Item, error) {
418		itemID = clean(itemID)
419		operator = clean(operator)
420		if err := requireNonEmpty("操作人", operator); err != nil {
421			return Item{}, err
422		}
423	
424		var closed Item
425		err := svc.store.mutate(func(d *Data) error {
426			it, _ := findItem(d, itemID)
427			if it == nil {
428				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
429			}
430			if it.Closed {
431				return fmt.Errorf("%w：事项 %s 已关闭，不能重复关闭", ErrHandoverState, itemID)
432			}
433			sh, _ := findShift(d, it.CurrentShiftID)
434			if sh == nil || sh.Closed {
435				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，关闭状态不能修改",
436					ErrShiftClosed, itemID, it.CurrentShiftID)
437			}
438			now := svc.now()
439			it.Closed = true
440			it.ClosedAt = &now
441			it.CloseOperator = operator
442			it.Events = append(it.Events, ItemEvent{At: now, Kind: "closed", Operator: operator})
443			closed = *it
444			return nil
445		})
446		return closed, err
447	}
448	
449	// CloseShift 结束班次。任一接班交接存在未确认接收的事项（待处理、退回、
450	// 处理结果缺失或无法识别）时不允许结束，其他交接已完成也不能放行；空清单
451	// 交接视为已完成，可以结束。
452	// 结束成功时把在班事项（本班新增与已接收，含结束前已关闭者）冻结为结束时记录；
453	// 校验或保存失败时不留下任何记录，班次保持进行中，也不改变交接结果、
454	// 事项归属与已保存的处理经过。
455	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
456		shiftID = clean(shiftID)
457		var result Shift
458		err := svc.store.mutate(func(d *Data) error {
459			sh, _ := findShift(d, shiftID)
460			if sh == nil {
461				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
462			}
463			if sh.Closed {
464				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
465			}
466			for i := range d.Handovers {
467				h := &d.Handovers[i]
468				if h.ToShiftID == sh.ID && !h.Completed() {
469					return fmt.Errorf("%w：接班交接 %s 仍有未确认接收的事项，班次不能结束",
470						ErrHandoverState, h.ID)
471				}
472			}
473			now := svc.now()
474			sh.Closed = true
475			sh.ClosedAt = &now
476	
477			// 冻结结束时在班的全部事项。退回或未确认的交接事项当前班次仍在交班
478			// 班次，不会被快照；结束前已关闭的事项保留关闭人与关闭时间。
479			record := &ShiftCloseRecord{Items: []CloseItemSnapshot{}}
480			for i := range d.Items {
481				it := &d.Items[i]
482				if it.CurrentShiftID != sh.ID {
483					continue
484				}
485				record.Items = append(record.Items, CloseItemSnapshot{
486					ItemID:        it.ID,
487					Content:       it.Content,
488					Severity:      it.Severity,
489					Constraints:   it.Constraints,
490					FollowOwner:   it.FollowOwner,
491					Closed:        it.Closed,
492					ClosedAt:      it.ClosedAt,
493					CloseOperator: it.CloseOperator,
494				})
495			}
496			sort.Slice(record.Items, func(i, j int) bool { return record.Items[i].ItemID < record.Items[j].ItemID })
497			sh.CloseRecord = record
498	
499			result = *sh
500			return nil
501		})
502		return result, err
503	}
504	
505	// CreateHandover 由交班班次向同岗位接班班次发起交接。
506	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
507	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
508	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
509	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
510	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
511	// 要求仅对首次发起生效。
512	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
513		fromShiftID = clean(fromShiftID)
514		toShiftID = clean(toShiftID)
515	
516		var result Handover
517		err := svc.store.mutate(func(d *Data) error {
518			from, _ := findShift(d, fromShiftID)
519			to, _ := findShift(d, toShiftID)
520			if from == nil {
521				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
522			}
523			if to == nil {
524				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
525			}
526			if from.ID == to.ID {
527				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
528			}
529			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
530			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
531			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
532			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
533			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
534			// 存在与交给自身的校验仍在其前。
535			for i := range d.Handovers {
536				if d.Handovers[i].FromShiftID == from.ID {
537					existing := &d.Handovers[i]
538					result = *existing
539					if existing.ToShiftID != to.ID {
540						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
541							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
542					}
543					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
544				}
545			}
546	
547			if from.Position != to.Position {
548				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
549					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
550			}
551	
552			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
553			// 交班班次已经结束，重叠区间须有说明。
554			if to.Closed {
555				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
556			}
557			if to.Start.Before(from.Start) {
558				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
559					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
560					from.ID, from.Start.Format(time.RFC3339))
561			}
562			if !from.Closed {
563				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
564					ErrShiftNotClosed, from.ID)
565			}
566			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
567				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
568					ErrOverlap, from.ID, to.ID)
569			}
570	
571			entries := []HandoverEntry{}
572			for i := range d.Items {
573				it := &d.Items[i]
574				if it.CurrentShiftID == from.ID && !it.Closed {
575					entries = append(entries, HandoverEntry{
576						ItemID:      it.ID,
577						Content:     it.Content,
578						Severity:    it.Severity,
579						Constraints: it.Constraints,
580						FollowOwner: it.FollowOwner,
581						Status:      EntryPending,
582					})
583				}
584			}
585			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
586	
587			d.HandoverSeq++
588			now := svc.now()
589			h := Handover{
590				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
591				Position:    from.Position,
592				FromShiftID: from.ID,
593				ToShiftID:   to.ID,
594				CreatedAt:   now,
595				Entries:     entries,
596			}
597			if len(entries) == 0 {
598				// 空清单直接完成。
599				h.CompletedAt = &now
600			}
601			d.Handovers = append(d.Handovers, h)
602			result = h
603			return nil
604		})
605		return result, err
606	}
