1	package handover
2	
3	import (
4		"errors"
5		"os"
6		"strings"
7		"testing"
8		"time"
9	)
10	
11	// breakSaving 在数据文件的临时写入路径上放一个目录，使 commit 的临时文件
12	// 写入必然失败（EISDIR）。这是“真正进入保存过程后”的失败：业务校验已全部
13	// 通过、内存变更已经发生，失败点在原子写盘阶段；与是否以 root 运行无关，
14	// 因而测试可在任意机器上独立重复。
15	func breakSaving(t *testing.T, f *fixture) {
16		t.Helper()
17		tmp := f.store.Path() + ".tmp"
18		if err := os.Mkdir(tmp, 0o755); err != nil {
19			t.Fatalf("制造保存失败：%v", err)
20		}
21	}
22	
23	// restoreSaving 移除故障路径，使保存恢复正常。
24	func restoreSaving(t *testing.T, f *fixture) {
25		t.Helper()
26		if err := os.RemoveAll(f.store.Path() + ".tmp"); err != nil {
27			t.Fatalf("恢复保存：%v", err)
28		}
29	}
30	
31	// assertLastItemStillPending 用当前打开的数据核对：失败的继续跟踪没有留下
32	// 任何半完成结果。
33	func assertLastItemStillPending(t *testing.T, f *fixture, hID, fromShift, toShift, lastID, otherID string, otherProcessedAt time.Time) {
34		t.Helper()
35	
36		// 交接：最后一项仍为待处理，当前处理人与处理时间显示尚未处理，没有本次
37		// 跟踪说明或新负责人，也没有退回轮次；整份交接未完成且无完成时间。
38		h, err := f.svc.GetHandover(hID)
39		if err != nil {
40			t.Fatalf("get handover: %v", err)
41		}
42		if h.Completed() || h.CompletedAt != nil {
43			t.Fatalf("保存失败后整份交接应继续未完成、不能留下完成时间：%+v", h)
44		}
45		e := findEntryOf(t, h, lastID)
46		if e.Status != EntryPending {
47			t.Fatalf("最后一项应仍为待处理，got %s", e.Status)
48		}
49		if e.Operator != "" || e.ProcessedAt != nil {
50			t.Fatalf("最后一项的当前处理人与处理时间应仍为尚未处理：%+v", e)
51		}
52		if e.TrackingNote != "" || e.FollowOwner != "李四" {
53			t.Fatalf("不应留下本次跟踪说明或新负责人：%+v", e)
54		}
55		if len(e.Rounds) != 0 {
56			t.Fatalf("失败尝试不应产生退回/补充经过：%+v", e.Rounds)
57		}
58		// 之前已经接收的其他事项及其处理信息保持原样。
59		oe := findEntryOf(t, h, otherID)
60		if oe.Status != EntryConfirmed || oe.Operator != "李四" ||
61			oe.ProcessedAt == nil || !oe.ProcessedAt.Equal(otherProcessedAt) {
62			t.Fatalf("已接收的其他事项处理信息应保持原样：%+v", oe)
63		}
64	
65		// 事项：仍留在交班班次，流经班次不增加接班班次，负责人不变，
66		// 事项历史不增加这次接收。
67		it, err := f.svc.GetItem(lastID)
68		if err != nil {
69			t.Fatalf("get item: %v", err)
70		}
71		if it.CurrentShiftID != fromShift {
72			t.Fatalf("事项应仍留在交班班次 %s，got %s", fromShift, it.CurrentShiftID)
73		}
74		if len(it.ShiftIDs) != 1 || it.ShiftIDs[0] != fromShift {
75			t.Fatalf("流经班次不应增加接班班次：%v", it.ShiftIDs)
76		}
77		if it.FollowOwner != "李四" {
78			t.Fatalf("事项后续负责人应保持原值，got %s", it.FollowOwner)
79		}
80		for _, ev := range it.Events {
81			if ev.Kind == "received" || strings.Contains(ev.Detail, "接班班次") {
82				t.Fatalf("事项处理经过不应增加这次失败的接收：%+v", ev)
83			}
84		}
85	
86		// 处理经过查询同样不出现这次接收，交接当前结果仍为待处理。
87		j, err := f.svc.ItemJourney(lastID)
88		if err != nil {
89			t.Fatalf("journey: %v", err)
90		}
91		if len(j.Results) != 1 || j.Results[0].Entry.Status != EntryPending {
92			t.Fatalf("处理经过中的交接当前结果应仍为待处理：%+v", j.Results)
93		}
94		for _, ev := range j.Events {
95			if ev.Kind == "track" || ev.Kind == "received" {
96				t.Fatalf("处理经过不应出现失败的继续跟踪接收：%+v", ev)
97			}
98			if ev.TrackingNote != "" {
99				t.Fatalf("处理经过不应留下失败尝试的跟踪说明：%+v", ev)
100			}
101		}
102	
103		// 交班班次的结束时事项记录保留原来的内容与负责人。
104		rep, err := f.svc.ShiftReport(fromShift)
105		if err != nil {
106			t.Fatalf("report from shift: %v", err)
107		}
108		snap := findCloseItem(rep, lastID)
109		if snap == nil || snap.FollowOwner != "李四" || snap.Content != "事项乙" {
110			t.Fatalf("交班班次结束时记录应保持原内容与负责人：%+v", snap)
111		}
112	
113		// 展示层与保存事实一致：未完成、尚未处理、无本次跟踪说明。
114		text := FormatHandover(h)
115		if !strings.Contains(text, "[未完成]") {
116			t.Fatalf("交接应显示未完成：\n%s", text)
117		}
118		if !strings.Contains(text, "处理人=尚未处理；处理时间=尚未处理") {
119			t.Fatalf("待处理项应显示尚未处理：\n%s", text)
120		}
121		if strings.Contains(text, "持续跟踪压力变化") || strings.Contains(text, "王五") {
122			t.Fatalf("失败的跟踪说明与新负责人不应出现在交接查询中：\n%s", text)
123		}
124	}
125	
126	// TestTrackSaveFailureAtomicRollback：接班人对最后一项待处理事项选择继续跟踪，
127	// 参数合法、状态允许、真正进入保存过程后本地写盘失败——操作必须明确返回保存
128	// 错误，且交接、事项、班次与处理经过都不留下半完成结果；失败前已保存的数据
129	// （含交班班次结束时记录）原样保留，重新打开后一致。保存恢复后对同一项再次
130	// 提交，按现有功能成功接收，处理经过只留下成功的这一次。
131	func TestTrackSaveFailureAtomicRollback(t *testing.T) {
132		f := newFixture(t)
133		a, b, items := prepareHandover(t, f)
134		h, err := f.svc.CreateHandover(a.ID, b.ID)
135		if err != nil {
136			t.Fatalf("create handover: %v", err)
137		}
138		idFirst, idLast := items[0].ID, items[1].ID // 事项甲、事项乙（事项丙已关闭）
139	
140		// 其中一项已经成功接收；最后一项仍待处理且属于交班班次。
141		confirmAt := tsDay(2, 17, 0)
142		f.svc.nowAt(func() time.Time { return confirmAt })
143		if _, err := f.svc.ProcessEntry(h.ID, idFirst, ActionConfirm, "李四", "", "", ""); err != nil {
144			t.Fatalf("confirm first: %v", err)
145		}
146		got, _ := f.svc.GetHandover(h.ID)
147		if got.Completed() {
148			t.Fatalf("前置：仍有一项待处理，交接不应完成")
149		}
150	
151		// 记录失败前已落盘的文件内容，并固定失败尝试的处理时刻。
152		rawBefore, err := os.ReadFile(f.store.Path())
153		if err != nil {
154			t.Fatalf("read data file: %v", err)
155		}
156		failAt := tsDay(2, 18, 0)
157		f.svc.nowAt(func() time.Time { return failAt })
158	
159		// 使下一次写盘在原子保存阶段失败。
160		breakSaving(t, f)
161		_, err = f.svc.ProcessEntry(h.ID, idLast, ActionTrack, "李四", "", "持续跟踪压力变化", "王五")
162		// 操作必须明确返回错误，且这是保存错误而不是业务拒绝
163		// （不能用缺少跟踪说明、负责人为空或事项已接收等来冒充）。
164		if err == nil {
165			t.Fatalf("保存失败时操作应返回错误")
166		}
167		if !strings.Contains(err.Error(), "写入数据文件失败") {
168			t.Fatalf("应明确返回保存阶段的错误，got %v", err)
169		}
170		if errors.Is(err, ErrInvalidInput) || errors.Is(err, ErrHandoverState) || errors.Is(err, ErrNotFound) {
171			t.Fatalf("参数合法、状态允许时的保存失败不应被报告为业务校验错误，got %v", err)
172		}
173	
174		// 当前打开的数据中不留半完成结果。
175		assertLastItemStillPending(t, f, h.ID, a.ID, b.ID, idLast, idFirst, confirmAt)
176	
177		// 失败前已保存的数据文件一个字节都不应改变（原子改名未发生）。
178		rawAfter, err := os.ReadFile(f.store.Path())
179		if err != nil {
180			t.Fatalf("read data file after failure: %v", err)
181		}
182		if string(rawAfter) != string(rawBefore) {
183			t.Fatalf("保存失败不得改动既有数据文件")
184		}
185	
186		// 退出后重新打开：交接进度、事项所在班次和后续负责人与失败前一致。
187		f.reopen(t)
188		assertLastItemStillPending(t, f, h.ID, a.ID, b.ID, idLast, idFirst, confirmAt)
189	
190		// 保存条件恢复后，对同一项再次提交继续跟踪：按现有功能成功接收。
191		restoreSaving(t, f)
192		successAt := tsDay(2, 19, 0)
193		f.svc.nowAt(func() time.Time { return successAt })
194		if _, err := f.svc.ProcessEntry(h.ID, idLast, ActionTrack, "李四", "", "持续跟踪压力变化", "王五"); err != nil {
195			t.Fatalf("恢复后继续跟踪应成功：%v", err)
196		}
197	
198		// 交接：最后一项只成功接收这一次，处理人与处理时间反映成功操作，
199		// 整份交接的完成时间以这次成功处理为准。
200		h2, err := f.svc.GetHandover(h.ID)
201		if err != nil {
202			t.Fatalf("get handover after retry: %v", err)
203		}
204		if !h2.Completed() || h2.CompletedAt == nil || !h2.CompletedAt.Equal(successAt) {
205			t.Fatalf("完成时间应以成功处理时刻 19:00 为准：%+v", h2)
206		}
207		le := findEntryOf(t, h2, idLast)
208		if le.Status != EntryTracking || le.Operator != "李四" || le.ProcessedAt == nil ||
209			!le.ProcessedAt.Equal(successAt) || le.TrackingNote != "持续跟踪压力变化" ||
210			le.FollowOwner != "王五" {
211			t.Fatalf("最后一项应为本次成功的继续跟踪：%+v", le)
212		}
213		if len(le.Rounds) != 0 {
214			t.Fatalf("失败尝试不应变成历史事实（无退回轮次）：%+v", le.Rounds)
215		}
216	
217		// 事项：保留编号进入接班班次，流经班次只含交班与接班两班，负责人与历史
218		// 只反映成功的这一次接收。
219		it, err := f.svc.GetItem(idLast)
220		if err != nil {
221			t.Fatalf("get item after retry: %v", err)
222		}
223		if it.ID != idLast || it.CurrentShiftID != b.ID {
224			t.Fatalf("应保留事项编号并进入接班班次：%+v", it)
225		}
226		if len(it.ShiftIDs) != 2 || it.ShiftIDs[0] != a.ID || it.ShiftIDs[1] != b.ID {
227			t.Fatalf("流经班次应只增加一次接班班次：%v", it.ShiftIDs)
228		}
229		if it.FollowOwner != "王五" {
230			t.Fatalf("事项后续负责人应为本次填写的新负责人，got %s", it.FollowOwner)
231		}
232		kinds := []string{}
233		received := 0
234		for _, ev := range it.Events {
235			kinds = append(kinds, ev.Kind)
236			if ev.Kind == "received" {
237				received++
238				if !strings.Contains(ev.Detail, "持续跟踪压力变化") || ev.Operator != "李四" {
239					t.Fatalf("接收记录应反映成功操作：%+v", ev)
240				}
241			}
242		}
243		if received != 1 || joinStrings(kinds) != "created,received" {
244			t.Fatalf("事项历史只应留下成功的这一次接收，got %v", kinds)
245		}
246	
247		// 处理经过：只展示成功的这一次继续跟踪，失败尝试不在任何事件中。
248		j, err := f.svc.ItemJourney(idLast)
249		if err != nil {
