259				if !ev.TimeKnown || !ev.At.Equal(successAt) || ev.Operator != "李四" ||
260					ev.TrackingNote != "持续跟踪压力变化" || ev.FollowOwner != "王五" {
261					t.Fatalf("成功接收事件内容不正确：%+v", ev)
262				}
263			}
264		}
265		if tracks != 1 {
266			t.Fatalf("应只有一次继续跟踪记录，got %d", tracks)
267		}
268		if len(j.Results) != 1 || j.Results[0].Entry.Status != EntryTracking {
269			t.Fatalf("交接当前结果应为继续跟踪：%+v", j.Results)
270		}
271	
272		// 重新打开后成功结果同样完整保留。
273		f.reopen(t)
274		h3, err := f.svc.GetHandover(h.ID)
275		if err != nil {
276			t.Fatalf("reopen get handover: %v", err)
277		}
278		if !h3.Completed() || h3.CompletedAt == nil || !h3.CompletedAt.Equal(successAt) {
279			t.Fatalf("重开后交接完成状态与完成时间应保留：%+v", h3)
280		}
281		it3, err := f.svc.GetItem(idLast)
282		if err != nil {
283			t.Fatalf("reopen get item: %v", err)
284		}
285		if it3.CurrentShiftID != b.ID || it3.FollowOwner != "王五" {
286			t.Fatalf("重开后事项所在班次与新负责人应保留：%+v", it3)
287		}
288		j3, err := f.svc.ItemJourney(idLast)
289		if err != nil {
290			t.Fatalf("reopen journey: %v", err)
291		}
292		if got := joinStrings(journeyKinds(j3)); got != "created,handover-init,track" {
293			t.Fatalf("重开后处理经过应只保留成功的一次，got %s", got)
294		}
