1	package handover
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11		"time"
12	)
13	
14	type fixture struct {
15		svc   *Service
16		store *Store
17		clock time.Time
18	}
19	
20	func newFixture(t *testing.T) *fixture {
21		t.Helper()
22		dir := t.TempDir()
23		store, err := Open(filepath.Join(dir, "data.json"))
24		if err != nil {
25			t.Fatalf("open: %v", err)
26		}
27		svc := NewService(store)
28		f := &fixture{
