		t.Fatalf("待处理项重新提交应报 ErrHandoverState，got %v", err)
	}
	got, _ := f.svc.GetHandover(h.ID)
	ea := findEntryOf(t, got, idA)
	if len(ea.Rounds) != 0 || ea.Status != EntryPending {
		t.Fatalf("状态错误时不应写入补充或退回记录：%+v", ea)
