11	// 在 2026-10-02 11:00+08:00 选择继续跟踪；事项后来负责人已改为钱七，但交接
12	// 快照里当时的跟踪负责人仍是王五。事项历史除建立事件外，接收事件由用例注入。
13	// 另有一个丙班 S003（旧说明可能指向它，但不存在对应交接清单）。
14	func journeyMergeRaw(receivedEventsJSON, processedAtJSON string) string {
15		return fmt.Sprintf(`{
16	  "shift_seq": 3, "item_seq": 1, "handover_seq": 1, "note_seq": 0,
17	  "shifts": [
18	    {"id":"S001","position":"调度","owner":"张三","start":"2026-10-02T08:00:00+08:00","end":"2026-10-02T16:00:00+08:00","created_at":"2026-10-02T08:00:00+08:00","closed":true,"closed_at":"2026-10-02T16:00:00+08:00"},
19	    {"id":"S002","position":"调度","owner":"李四","start":"2026-10-02T16:00:00+08:00","end":"2026-10-02T23:00:00+08:00","created_at":"2026-10-02T08:00:00+08:00","closed":false},
20	    {"id":"S003","position":"调度","owner":"赵六","start":"2026-10-02T16:00:00+08:00","end":"2026-10-02T23:30:00+08:00","created_at":"2026-10-02T08:00:00+08:00","closed":true,"closed_at":"2026-10-02T23:30:00+08:00"}
21	  ],
