package handover

import (
	"fmt"
	"os"
	"strings"
	"testing"
)

// 合并接收记录场景共用的旧数据：H001 由甲班 S001 交给乙班 S002，接班人李四
// 在 2026-10-02 11:00+08:00 选择继续跟踪；事项后来负责人已改为钱七，但交接
// 快照里当时的跟踪负责人仍是王五。事项历史除建立事件外，接收事件由用例注入。
// 另有一个丙班 S003（旧说明可能指向它，但不存在对应交接清单）。
func journeyMergeRaw(receivedEventsJSON, processedAtJSON string) string {
	return fmt.Sprintf(`{
  "shift_seq": 3, "item_seq": 1, "handover_seq": 1, "note_seq": 0,
  "shifts": [
    {"id":"S001","position":"调度","owner":"张三","start":"2026-10-02T08:00:00+08:00","end":"2026-10-02T16:00:00+08:00","created_at":"2026-10-02T08:00:00+08:00","closed":true,"closed_at":"2026-10-02T16:00:00+08:00"},
    {"id":"S002","position":"调度","owner":"李四","start":"2026-10-02T16:00:00+08:00","end":"2026-10-02T23:00:00+08:00","created_at":"2026-10-02T08:00:00+08:00","closed":false},
    {"id":"S003","position":"调度","owner":"赵六","start":"2026-10-02T16:00:00+08:00","end":"2026-10-02T23:30:00+08:00","created_at":"2026-10-02T08:00:00+08:00","closed":true,"closed_at":"2026-10-02T23:30:00+08:00"}
  ],
  "items": [
    {"id":"I001","origin_shift_id":"S001","shift_ids":["S001","S002"],"current_shift_id":"S002",
     "content":"泵房压力异常","severity":"important","constraints":"夜间禁动","follow_owner":"钱七",
     "created_at":"2026-10-02T09:00:00+08:00",
     "events":[
       {"at":"2026-10-02T09:00:00+08:00","kind":"created","detail":"事项建立"}%s
     ]}
  ],
  "handovers": [
    {"id":"H001","position":"调度","from_shift_id":"S001","to_shift_id":"S002",
     "created_at":"2026-10-02T10:00:00+08:00","completed_at":%s,
     "entries":[
       {"item_id":"I001","content":"泵房压力异常","severity":"important","constraints":"夜间禁动",
        "follow_owner":"王五","status":"tracking","operator":"李四","processed_at":%s,
        "tracking_note":"每两小时记录压力"}
     ]}
  ],
  "notes": []
}`, receivedEventsJSON, processedAtJSON, processedAtJSON)
}

// 两类接收说明文本。
const (
	// 新版本格式：明确记载交接编号、两班与接收方式，与 H001 一致。
	canonicalTrackToB = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"交接 H001（S001 -> S002）接班班次接收：继续跟踪；跟踪说明：每两小时记录压力；后续负责人：王五"}`
	// 旧格式：同操作人同时刻，但明确记载交给丙班 S003、接收方式为确认接收；
	// 没有对应的交接清单，也不带任何交接编号。
	legacyConfirmToC = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"接班班次 S003 接收：确认接收"}`
	// 新格式，但两班与交接编号都对、接收方式却记载为确认接收。
	canonicalConfirmToB = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"交接 H001（S001 -> S002）接班班次接收：确认接收"}`
	// 没有任何明确归属信息的自由文本说明。
	freeTextReceive = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"当时口头打过招呼，先收下来"}`
	// 新格式但记载了另一个交接编号 H999（无此交接）。
	otherHandoverTrack = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"交接 H999（S001 -> S002）接班班次接收：继续跟踪；跟踪说明：每两小时记录压力；后续负责人：王五"}`
	// 旧版本格式，记载的接班班次与接收方式都与 H001 一致（无交接编号）。
	legacyTrackToB = `,{"at":"2026-10-02T11:00:00+08:00","kind":"received","operator":"李四","detail":"接班班次 S002 接收：继续跟踪；跟踪说明：每两小时记录压力；后续负责人：王五"}`
	// 新格式且与 H001 一致，但时间用另一时区表示同一实际时刻（11:00+08:00 == 10:00+07:00）。
	canonicalTrackToBTZ = `,{"at":"2026-10-02T10:00:00+07:00","kind":"received","operator":"李四","detail":"交接 H001（S001 -> S002）接班班次接收：继续跟踪；跟踪说明：每两小时记录压力；后续负责人：王五"}`
)

func countKind(events []JourneyEvent, kind string) int {
	n := 0
	for _, ev := range events {
		if ev.Kind == kind {
			n++
		}
	}
	return n
}

// TestItemJourneyMergeReceptionSameOperatorSameTime：操作人与实际时刻相同并不
// 足以判定同一次接收。交给丙班的旧确认接收说明必须完整保留，H001 交给乙班的
// 继续跟踪只展示一次；两条历史在事项事件里的存放先后不能决定哪一条被隐藏；
// 旧说明没有对应交接清单时，既不能丢掉它，也不能凭空补上交接编号。
func TestItemJourneyMergeReceptionSameOperatorSameTime(t *testing.T) {
	for _, order := range []struct{ name, events string }{
		{"旧丙班说明在前", legacyConfirmToC + canonicalTrackToB},
		{"旧丙班说明在后", canonicalTrackToB + legacyConfirmToC},
	} {
		t.Run(order.name, func(t *testing.T) {
			svc := openLegacyService(t, journeyMergeRaw(order.events, `"2026-10-02T11:00:00+08:00"`))
			j, err := svc.ItemJourney("I001")
			if err != nil {
				t.Fatalf("journey: %v", err)
			}
			if countKind(j.Events, "track") != 1 {
				t.Fatalf("交给乙班的继续跟踪应只展示一次：%v", journeyKinds(j))
			}
			if countKind(j.Events, "received") != 1 {
				t.Fatalf("交给丙班的旧确认接收说明应原样保留一条：%v", journeyKinds(j))
			}
			if countKind(j.Events, "confirm") != 0 {
				t.Fatalf("H001 中不存在确认接收事件，丙班说明不应被改写成交接确认：%v", journeyKinds(j))
			}
			var standalone *JourneyEvent
			for i := range j.Events {
				if j.Events[i].Kind == "received" {
					standalone = &j.Events[i]
				}
			}
			if standalone == nil || !strings.Contains(standalone.Detail, "接班班次 S003 接收：确认接收") {
				t.Fatalf("保留的应是交给丙班的原说明：%+v", standalone)
			}
			if standalone.HandoverID != "" || standalone.ToShift != "" {
				t.Fatalf("无交接清单的旧说明不能凭空补交接编号或接班班次字段：%+v", standalone)
			}

			text := FormatItemJourney(j)
			if !strings.Contains(text, "接班班次 S003 接收：确认接收") {
				t.Fatalf("展示应完整保留交给丙班的原说明：\n%s", text)
			}
			if strings.Count(text, "交接 H001（S001 -> S002）继续跟踪") != 1 {
				t.Fatalf("交给乙班的继续跟踪应只出现一次：\n%s", text)
			}
			if !strings.Contains(text, "跟踪说明=每两小时记录压力") ||
				!strings.Contains(text, "后续负责人=王五") {
				t.Fatalf("继续跟踪应带出当时的跟踪说明与后续负责人：\n%s", text)
			}
			// 事项后来修改的负责人只体现在开头最新状态，不替换当时记录。
			if !strings.Contains(text, "后续负责人：钱七") {
				t.Fatalf("查询开头仍应展示事项最新负责人钱七：\n%s", text)
			}
			if len(j.Results) != 1 || j.Results[0].HandoverID != "H001" ||
				j.Results[0].Entry.Status != EntryTracking {
				t.Fatalf("各次交接当前结果应保持不变：%+v", j.Results)
			}
		})
	}
}

// TestItemJourneyMergeReceptionDistinguishingFacts：记载的接收方式、交接编号
// 不同，或说明根本没有明确归属信息时，事项历史各自保留；记载一致（含旧版本
// 格式、不同时区表示同一时刻）时才合并为同一次接收。
func TestItemJourneyMergeReceptionDistinguishingFacts(t *testing.T) {
	cases := []struct {
		name           string
		events         string
		processedAt    string
		wantStandalone int // 期望保留的事项自身 received 事件条数
	}{
		{"记载接收方式不同", canonicalConfirmToB, `"2026-10-02T11:00:00+08:00"`, 1},
		{"说明无明确归属信息", freeTextReceive, `"2026-10-02T11:00:00+08:00"`, 1},
		{"记载另一个交接编号", otherHandoverTrack, `"2026-10-02T11:00:00+08:00"`, 1},
		{"旧格式记载一致应合并", legacyTrackToB, `"2026-10-02T11:00:00+08:00"`, 0},
		{"新格式记载一致应合并", canonicalTrackToB, `"2026-10-02T11:00:00+08:00"`, 0},
		{"不同时区同一时刻应合并", canonicalTrackToBTZ, `"2026-10-02T11:00:00+08:00"`, 0},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			svc := openLegacyService(t, journeyMergeRaw(tc.events, tc.processedAt))
			j, err := svc.ItemJourney("I001")
			if err != nil {
				t.Fatalf("journey: %v", err)
			}
			if countKind(j.Events, "track") != 1 {
				t.Fatalf("H001 的继续跟踪应始终展示一次：%v", journeyKinds(j))
			}
			if got := countKind(j.Events, "received"); got != tc.wantStandalone {
				t.Fatalf("事项自身接收记录保留条数 want %d, got %d：%v", tc.wantStandalone, got, journeyKinds(j))
			}
		})
	}
}

// TestItemJourneyMergeReceptionDoesNotRewrite：单纯查询不改写任何历史、不移动
// 事项、不改变交接完成情况。
func TestItemJourneyMergeReceptionDoesNotRewrite(t *testing.T) {
	raw := journeyMergeRaw(legacyConfirmToC+canonicalTrackToB, `"2026-10-02T11:00:00+08:00"`)
	svc := openLegacyService(t, raw)
	if _, err := svc.ItemJourney("I001"); err != nil {
		t.Fatalf("journey: %v", err)
	}
	// 重新打开同一文件，落盘内容必须与查询前逐字节一致。
	path := svc.store.Path()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read: %v", err)
	}
	if string(b) != raw {
		t.Fatalf("单纯查询不应重写数据文件")
	}
	it, err := svc.GetItem("I001")
	if err != nil {
		t.Fatalf("get item: %v", err)
	}
	if it.CurrentShiftID != "S002" || it.FollowOwner != "钱七" {
		t.Fatalf("查询不应移动事项或替换负责人：%+v", it)
	}
	h, err := svc.GetHandover("H001")
	if err != nil || !h.Completed() {
		t.Fatalf("交接完成情况不应改变：%+v err=%v", h, err)
	}
}

// Command handover 是本地班次交接与未关闭事项的命令行入口。
//
// 数据默认保存在当前目录 handover-data.json，可用全局参数 --data 或环境变量
// HANDOVER_DATA 指定。时间统一使用带时区偏移的 RFC3339，如
// 2026-10-02T08:00:00+08:00。
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	"github.com/bengzyyys/shift-handover/handover"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

const usageText = `用法：handover [--data 文件] <命令> [参数]

数据持久化在本地 JSON 文件中，退出后重新打开数据仍在。
时间使用带时区的 RFC3339，例如 2026-10-02T08:00:00+08:00。

班次：
  shift-add      建立班次        --position 岗位 --owner 负责人 --start 开始 --end 结束
                                 [--note 重叠说明（与同岗位已存班次区间重叠时必填）]
  shift-list     列出全部班次
  shift-close    结束班次        --id 班次编号
  shift-show     按班次查询      --id 班次编号（完整事项/交接/结果）

重叠说明：
  note-add       为重叠班次填说明 --a 班次 --b 班次 --note 说明
  note-list      查看班次涉及的重叠说明 --id 班次

事项：
  item-add       新增事项        --shift 班次 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-update    修改事项        --id 事项编号 --content 内容 \
                                 --severity normal|important|urgent \
                                 [--constraints 限制条件] --follow 后续负责人
  item-close     关闭事项        --id 事项编号 --operator 操作人
  item-show      查询事项        --id 事项编号（最新状态、完整处理经过与各次交接当前结果）

交接：
  handover-create   发起交接      --from 交班班次 --to 接班班次
  handover-list     列出全部交接
  handover-show     查看交接      --id 交接编号
  handover-process  接班人处理单项 --id 交接编号 --item 事项编号 \
                                 --action confirm|return|track --operator 操作人 \
                                 [--reason 退回原因] [--note 跟踪说明] [--follow 后续负责人]
  handover-resubmit 交班人补充并重新提交退回项 \
                                 --id 交接编号 --item 事项编号 \
                                 --operator 操作人 --supplement 补充说明
`

func run(argv []string, stdout, stderr io.Writer) int {
	args := append([]string(nil), argv...)
	dataPath, rest := splitDataFlag(args, os.Getenv("HANDOVER_DATA"))
	if dataPath == "" {
		dataPath = "handover-data.json"
	}

	if len(rest) == 0 || rest[0] == "-h" || rest[0] == "--help" || rest[0] == "help" {
		fmt.Fprint(stdout, usageText)
		return 0
	}

	cmd, cmdArgs := rest[0], rest[1:]
	store, err := handover.Open(dataPath)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	svc := handover.NewService(store)

	out, err := dispatch(svc, cmd, cmdArgs)
	if err != nil {
		fmt.Fprintf(stderr, "错误：%v\n", err)
		return 1
	}
	if out != "" {
		fmt.Fprint(stdout, out)
		if len(out) > 0 && out[len(out)-1] != '\n' {
			fmt.Fprintln(stdout)
		}
	}
	return 0
}

// valueFlags 是各子命令会带一个值的字符串参数。提取全局 --data 时，
// 这些参数后面的一个 token 是它的值：即使恰好写成 --data 或 --data=...，
// 也只是参数值（如事项内容、限制条件），不能当作数据文件参数取走。
var valueFlags = map[string]bool{
	"id": true, "position": true, "owner": true, "start": true, "end": true,
	"a": true, "b": true, "note": true, "shift": true, "content": true,
	"severity": true, "constraints": true, "follow": true, "operator": true,
	"from": true, "to": true, "item": true, "action": true, "reason": true,
	"supplement": true,
}

// splitDataFlag 从全部输入中抽出全局 --data（--data 路径 与 --data=路径 两种
// 形式，命令前后均可），返回数据文件路径与其余参数。已知参数的 --name value
// 形式中，value 原样保留，不参与 --data 判定；env 为未显式指定时的回退值。
func splitDataFlag(args []string, env string) (dataPath string, rest []string) {
	dataPath = env
	rest = make([]string, 0, len(args))
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if name, ok := flagName(arg); ok && name != "data" && valueFlags[name] {
			// 其他参数的 --name value 形式：下一个 token 是它的值，原样保留。
			rest = append(rest, arg)
			if i+1 < len(args) {
				rest = append(rest, args[i+1])
				i++
			}
			continue
		}
		switch {
		case arg == "--data" && i+1 < len(args):
			dataPath = args[i+1]
			i++
		case len(arg) > 7 && arg[:7] == "--data=":
			dataPath = arg[7:]
		default:
			rest = append(rest, arg)
		}
	}
	return dataPath, rest
}

// flagName 解析 -name / --name 形式的参数名；带 = 的形式值已内联，返回 false。
func flagName(arg string) (string, bool) {
	if !strings.HasPrefix(arg, "-") || strings.Contains(arg, "=") {
		return "", false
	}
	name := strings.TrimLeft(arg, "-")
	return name, name != ""
}

func dispatch(svc *handover.Service, cmd string, args []string) (string, error) {
	fs := flag.NewFlagSet(cmd, flag.ContinueOnError)
	fs.SetOutput(io.Discard)

	var (
		id, position, owner, startS, endS              string
		a, b                                           string
		shift, content, severityS, constraints, follow string
		operator, from, to                             string
		item, actionS, reason, note, supplement        string
	)
	fs.StringVar(&id, "id", "", "记录编号")
	fs.StringVar(&position, "position", "", "岗位")
	fs.StringVar(&owner, "owner", "", "负责人")
	fs.StringVar(&startS, "start", "", "开始时间 RFC3339")
	fs.StringVar(&endS, "end", "", "结束时间 RFC3339")
	fs.StringVar(&a, "a", "", "班次编号 A")
	fs.StringVar(&b, "b", "", "班次编号 B")
	// note-add 时为重叠说明；handover-process --action track 时为跟踪说明。
	fs.StringVar(&note, "note", "", "重叠说明 / 跟踪说明")
	fs.StringVar(&shift, "shift", "", "班次编号")
	fs.StringVar(&content, "content", "", "事项内容")
	fs.StringVar(&severityS, "severity", "", "严重程度 normal|important|urgent")
	fs.StringVar(&constraints, "constraints", "", "限制条件（可空）")
	// follow 同时用于后续负责人（新增/修改事项）与跟踪后续负责人（track）。
	fs.StringVar(&follow, "follow", "", "后续负责人")
	fs.StringVar(&operator, "operator", "", "操作人")
	fs.StringVar(&from, "from", "", "交班班次编号")
	fs.StringVar(&to, "to", "", "接班班次编号")
	fs.StringVar(&item, "item", "", "事项编号")
	fs.StringVar(&actionS, "action", "", "confirm|return|track")
	fs.StringVar(&reason, "reason", "", "退回原因")
	fs.StringVar(&supplement, "supplement", "", "补充说明")
	if err := fs.Parse(args); err != nil {
		return "", err
	}

	switch cmd {
	case "shift-add":
		start, err := parseTime("--start", startS)
		if err != nil {
			return "", err
		}
		end, err := parseTime("--end", endS)
		if err != nil {
			return "", err
		}
		sh, err := svc.CreateShift(position, owner, start, end, note)
		if err != nil {
			return "", err
		}
		return "已建立班次 " + handover.FormatShift(sh), nil

	case "shift-list":
		shifts := svc.ListShifts()
		if len(shifts) == 0 {
			return "（暂无班次）", nil
		}
		out := ""
		for _, sh := range shifts {
			out += handover.FormatShift(sh) + "\n"
		}
		return out, nil

	case "shift-close":
		sh, err := svc.CloseShift(id)
		if err != nil {
			return "", err
		}
		return "已结束班次 " + handover.FormatShift(sh), nil

	case "shift-show":
		rep, err := svc.ShiftReport(id)
		if err != nil {
			return "", err
		}
		return handover.FormatReport(rep), nil

	case "note-add":
		n, err := svc.AddOverlapNote(a, b, note)
		if err != nil {
			return "", err
		}
		return "已保存重叠说明 " + handover.FormatOverlapNote(n), nil

	case "note-list":
		notes := svc.OverlapNotes(id)
		if len(notes) == 0 {
			return "（无重叠说明）", nil
		}
		out := ""
		for _, n := range notes {
			out += handover.FormatOverlapNote(n) + "\n\n"
		}
		return out, nil

	case "item-add":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.AddItem(shift, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已新增事项\n" + handover.FormatItem(it), nil

	case "item-update":
		sev, err := handover.ParseSeverity(severityS)
		if err != nil {
			return "", err
		}
		it, err := svc.UpdateItem(id, content, sev, constraints, follow)
		if err != nil {
			return "", err
		}
		return "已修改事项\n" + handover.FormatItem(it), nil

	case "item-close":
		it, err := svc.CloseItem(id, operator)
		if err != nil {
			return "", err
		}
		return "已关闭事项\n" + handover.FormatItem(it), nil

	case "item-show":
		j, err := svc.ItemJourney(id)
		if err != nil {
			return "", err
		}
		return handover.FormatItemJourney(j), nil

	case "handover-create":
		h, err := svc.CreateHandover(from, to)
		if err != nil {
			if errors.Is(err, handover.ErrHandoverExists) {
				// 重复发起返回已有记录，不视为失败。
				return "已存在交接记录（重复发起，返回已有记录）\n" + handover.FormatHandover(h), nil
			}
			return "", err
		}
		return "已发起交接\n" + handover.FormatHandover(h), nil

	case "handover-list":
		hs := svc.ListHandovers()
		if len(hs) == 0 {
			return "（暂无交接记录）", nil
		}
		out := ""
		for _, h := range hs {
			out += handover.FormatHandover(h) + "\n"
		}
		return out, nil

	case "handover-show":
		h, err := svc.GetHandover(id)
		if err != nil {
			return "", err
		}
		return handover.FormatHandover(h), nil

	case "handover-process":
		action, err := handover.ParseAction(actionS)
		if err != nil {
			return "", err
		}
		h, err := svc.ProcessEntry(id, item, action, operator, reason, note, follow)
		if err != nil {
			return "", err
		}
		return "已处理\n" + handover.FormatHandover(h), nil

	case "handover-resubmit":
		h, err := svc.ResubmitReturned(id, item, operator, supplement)
		if err != nil {
			return "", err
		}
		return "已补充说明并重新提交\n" + handover.FormatHandover(h), nil

	default:
		return "", fmt.Errorf("未知命令 %q，运行 handover help 查看用法", cmd)
	}
}

func parseTime(name, s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, fmt.Errorf("%s 不能为空，格式为带时区的 RFC3339（如 2026-10-02T08:00:00+08:00）", name)
	}
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return time.Time{}, fmt.Errorf("%s 时间格式无效：%w（应为 RFC3339，如 2026-10-02T08:00:00+08:00）", name, err)
	}
	return t, nil
}

